pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor, address target) public {
        vm.assume(actor != address(0));
        vm.assume(target != address(0));
        vm.assume(actor != target);
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.deal(actor, amount);
        vm.deal(target, amount);

        vm.prank(target);
        c.addToBalance{value: amount}();

        uint256 targetBalanceBefore = c.getBalance(target);

        vm.prank(actor);
        c.addToBalance{value: amount}();

        uint256 totalUsers = c.getBalance(actor) + c.getBalance(target);
        assertTrue(totalUsers == address(c).balance);
    }
}
